//go:build ignore

package main

import (
	"log"
	"net/http"
	"os"
	"time"

	"entgo.io/ent/entc"
	"entgo.io/ent/entc/gen"
	"github.com/lrstanley/entrest"
	"github.com/lrstanley/x/entx/observe"
	"github.com/ogen-go/ogen"
	"github.com/ogen-go/ogen/jsonschema"
)

const header = `// Copyright (c) Liam Stanley <liam@liam.sh>. All rights reserved. Use of
// this source code is governed by the MIT license that can be found in
// the LICENSE file.
//
// DO NOT EDIT, CODE GENERATED BY entc.`

func checkError(err error) {
	if err != nil {
		log.Fatal(err)
	}
}

// withFieldProperty adds the "field" property to an error response schema, which
// is set for validation and constraint errors (see models.ErrorHandler).
func withFieldProperty(schema *ogen.Schema) *ogen.Schema {
	schema.Properties = append(schema.Properties, ogen.Property{
		Name: "field",
		Schema: &ogen.Schema{
			Type:        "string",
			Description: "The name of the invalid field, for validation and constraint errors (when known). The error message is then prefixed with \"<field>: \".",
			Example:     jsonschema.RawValue(`"regex_match"`),
		},
	})
	return schema
}

func main() {
	schemaPath := "./schema"
	rest, err := entrest.NewExtension(&entrest.Config{
		SpecFromPath:          "../../cmd/httpserver/base-openapi.json",
		MaxItemsPerPage:       500,
		Handler:               entrest.HandlerChi,
		StrictMutate:          true,
		GlobalRequestHeaders:  entrest.RequestIDHeader,
		GlobalResponseHeaders: entrest.RateLimitHeaders,
		GlobalErrorResponses: entrest.DefaultErrorResponses.Append(entrest.ErrorResponses{
			http.StatusBadRequest: withFieldProperty(entrest.ErrorResponseObject(http.StatusBadRequest)),
			http.StatusConflict:   withFieldProperty(entrest.ErrorResponseObject(http.StatusConflict)),
		}),
	})
	checkError(err)

	// Guild event observers wake live event streams (see GuildEventNotifier), and
	// guild config observers wake the worker, so config changes apply right away.
	extensions := entc.Extensions(rest, observe.New(&observe.Config{Nodes: []string{"GuildEvent", "GuildConfig", "GuildAdminConfig"}}))

	// entrest patches the config annotations in-place, so each generation pass
	// needs a fresh config.
	getConfig := func() *gen.Config {
		return &gen.Config{
			Target:  "./ent/",
			Schema:  "github.com/lrstanley/spectrograph/internal/database/schema",
			Package: "github.com/lrstanley/spectrograph/internal/database/ent",
			Header:  header,
			Features: []gen.Feature{
				gen.FeaturePrivacy,
				gen.FeatureEntQL,
				gen.FeatureUpsert,
				gen.FeatureIntercept,
				gen.FeatureExecQuery,
			},
		}
	}

	start := time.Now()

	// The schema policies import generated code, so bootstrap without them if the
	// generated code doesn't exist yet.
	if _, err := os.Stat("./ent/privacy/privacy.go"); err != nil && os.IsNotExist(err) {
		checkError(entc.Generate(schemaPath, getConfig(), extensions, entc.BuildTags("skippolicy")))
		log.Printf("bootstrap (no policies) took: %s", time.Since(start))
	}

	checkError(entc.Generate(schemaPath, getConfig(), extensions))
	log.Printf("generation completed (all): %s", time.Since(start))
}
